mapper.select:
select id, batch_no, merchant_id, period_start, period_end, total_amount, detail_count,
       success_count, failed_count, status, idempotency_key, reviewer_id, reviewed_at,
       create_time, update_time
from settlement_batch

    and merchant_id = #{merchantId}
    and status = #{status}
    and batch_no = #{batchNo}

order by id desc
